final class ImageCache {
    private let cache = NSCache<NSString, UIImage>()
    init() { cache.countLimit = 200; cache.totalCostLimit = 32 << 20 }   // 32 MB

    func image(for key: String) -> UIImage? { cache.object(forKey: key as NSString) }
    func store(_ image: UIImage, for key: String, bytes: Int) {
        cache.setObject(image, forKey: key as NSString, cost: bytes)
    }
    func invalidate(_ key: String) { cache.removeObject(forKey: key as NSString) }
}
